output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "An agent must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking or releasing a cart, the agent is obliged to retrieve a cart again before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "park_only_in_wide_cross_aisles",
    "text": "Carts may only be parked in wide cross-aisles away from shelves.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "shelf_interact_needs_cart_except_single_file",
    "text": "Shelf interactions require a cart unless the shelf is being accessed from a single-file aisle where carts are not allowed.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "adjShelf",
          "INTERACT",
          {
            "not": "hasCart"
          },
          {
            "not": "singleFileShelfAisle"
          }
        ]
      }
    }
  },
  {
    "id": "return_from_single_file_to_cart",
    "text": "After taking an item by hand in a single-file shelf aisle, the agent is obliged to return and pick up the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "handPickInSingleFile": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "handPickInSingleFile",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "lower_shelf_lane_no_north_or_west",
    "text": "In the lower wide shelf lane with shelves on the north side, cart users must not leave a shelf position by moving north or west.",
    "abstraction": {
      "state_properties": {
        "lowerNorthShelfLane": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "lowerNorthShelfLane",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_wandering_except_narrow_visit",
    "text": "After leaving the entrance area, moving without a cart is prohibited except while parking beside or traversing a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideCartParkingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entranceOrCartBay",
            "singleFileShelfAisle",
            "wideCartParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  }
]
